
const initialBindings=[
{id:'xmesh',repo:'demo-team/xmesh',source:'account',account:'build-team',concurrency:2,labels:['macOS','ARM64'],public:false,paused:false,instances:[{id:1,name:'xmesh-mac-01',state:'busy',job:'build · macOS arm64',since:'19:26:08',last:'test · succeeded',restarts:0},{id:2,name:'xmesh-mac-02',state:'idle',last:'lint · succeeded',since:'19:24:30',restarts:0}]},
{id:'desktop',repo:'demo-team/desktop',source:'account',account:'build-team',concurrency:1,labels:['desktop'],public:false,paused:false,instances:[{id:1,name:'desktop-mac-01',state:'idle',last:'typecheck · succeeded',since:'19:22:18',restarts:1}]},
{id:'docs',repo:'demo-team/docs',source:'token',account:null,concurrency:1,labels:['docs'],public:true,paused:false,instances:[{id:1,name:'docs-mac-01',state:'broken',problem:'运行器注册已失效，需要重新注册。',since:'19:18:42',restarts:2}]}
];
let bindings=structuredClone(initialBindings),accounts=[{id:'build-team',login:'build-team',host:'github.com',hint:'示例凭据 · 已保存'}],tab='repos',scene='sample',query='',statusFilter='all',bindingMode='account',pendingBind=null;
const stateNames={busy:'运行任务',idle:'空闲就绪',broken:'需要处理',stopped:'已停止',stopping:'等待任务结束'};
const stateTone=s=>s==='broken'?'warn':['stopped','stopping'].includes(s)?'neutral':'ok';
function counts(){const instances=bindings.flatMap(b=>b.instances);return{all:instances.length,busy:instances.filter(i=>i.state==='busy'||i.state==='stopping').length,idle:instances.filter(i=>i.state==='idle').length,broken:instances.filter(i=>i.state==='broken').length}}
function repoCards(){const filtered=bindings.filter(b=>(b.repo+' '+b.labels.join(' ')).toLowerCase().includes(query.toLowerCase())&&(statusFilter==='all'||statusFilter==='paused'&&b.paused||statusFilter==='attention'&&b.instances.some(i=>i.state==='broken')||statusFilter==='busy'&&b.instances.some(i=>i.state==='busy')));if(!filtered.length)return empty(bindings.length?'没有符合条件的仓库':'绑定你的第一个仓库',bindings.length?'调整搜索条件，查看其他绑定。':'连接 GitHub 仓库，让本机托管 Actions 运行器。',bindings.length?'reset-search':'add',bindings.length?'重置筛选':'添加仓库');return filtered.map(b=>`<article class="repo-card ${b.instances.some(i=>i.state==='broken')?'issue':''}"><div class="repo-heading"><span class="repo-icon">${icon('folder')}</span><div class="repo-heading-main"><div class="repo-title"><strong>${esc(b.repo)}</strong>${chip(b.public?'公开':'私有')}${b.paused?chip('已暂停','warn'):''}</div><p>${b.source==='account'?'账号 '+esc(b.account):b.source==='token'?'注册令牌绑定':'接管已有运行器'} · ${b.concurrency} 个实例</p></div><div class="repo-heading-actions"><button class="button small" data-toggle="${b.id}">${b.paused?'恢复':'暂停'}</button><button class="icon-button" data-settings="${b.id}" aria-label="管理 ${esc(b.repo)}">${icon('sliders')}</button></div></div><div class="repo-metadata"><span class="caption">运行标签</span><span class="tag-row">${chip('xmesh','green')}${b.labels.map(l=>chip(l)).join('')}</span></div>${b.instances.map(i=>`<div class="instance-row"><span class="instance-name">${i.name}</span>${state(stateNames[i.state],stateTone(i.state))}<span class="instance-job"><strong>${i.job?esc(i.job):i.state==='broken'?'等待重新注册':i.state==='stopped'?'接单已暂停':'等待新任务'}</strong><small>${i.job?'开始于 '+i.since:i.last?'最近：'+esc(i.last):'状态更新于 '+i.since}</small></span><button class="icon-button" data-instance="${b.id}:${i.id}" aria-label="查看 ${i.name}">${icon('chevron')}</button></div>`).join('')}${b.instances.some(i=>i.state==='broken')?`<div class="repo-issue">${icon('info')}<span>运行器注册已失效</span><button data-repair="${b.id}">重新注册 →</button></div>`:''}</article>`).join('')}
function ciSide(){const c=counts();return `<aside class="module-side"><section class="module-box"><div class="box-heading"><h3>运行环境</h3>${icon('device')}</div><div class="network-health">${icon('shield')}<div><strong>内核托管中</strong><small>xiaosong-mac · macOS ARM64</small></div></div>${facts([['运行器实例',`${c.all} 个`],['安装包','使用本机缓存'],['任务期间','阻止系统睡眠'],['退出时等待','最多 30 分钟']])}<button class="plain-link" data-open-tab="environment">查看运行设置 ${icon('arrow')}</button></section><section class="module-box"><div class="box-heading"><h3>GitHub 账号</h3><button class="plain-link" data-open-tab="accounts">管理 ${icon('chevron')}</button></div>${accounts.length?`<div class="account-identity"><span class="account-avatar">B</span><span><strong>${esc(accounts[0].login)}</strong><small>${esc(accounts[0].host)}</small></span></div><p>用于查询仓库和注册运行器。</p>`:`<p>连接账号后，可直接选择仓库。</p><button class="button small" data-action="account-add">添加账号</button>`}</section><section class="module-box"><h3>在工作流中使用</h3><p>通过标签指定本机的运行器。</p><pre class="code-box">runs-on:
  - self-hosted
  - xmesh
  - xmesh-xiaosong-mac</pre><button class="plain-link" style="margin-top:12px" data-copy="runs-on: [self-hosted, xmesh, xmesh-xiaosong-mac]">${icon('copy')}复制 runs-on</button></section></aside>`}
function render(){const c=counts();const heading=`<div class="breadcrumb">模块 <span>/</span><strong>CI 运行器</strong></div><div class="page-heading"><div><h1>CI 运行器</h1><p>绑定仓库，让构建和测试在这台设备上持续运行。</p></div><div class="heading-actions"><button class="button secondary-action" data-action="refresh">${icon('refresh')}刷新</button><button class="button primary" data-action="add">${icon('plus')}添加仓库</button></div></div><section class="module-summary"><div class="summary-main"><span class="summary-avatar">${icon('runner')}</span><div><h2>xiaosong-mac ${chip('本机')}</h2><p>GitHub Actions<span>·</span>macOS ARM64<span>·</span>${state('托管服务已就绪')}</p></div></div><span class="summary-separator"></span><div class="summary-numbers"><div><strong>${bindings.length}</strong><span>仓库绑定</span></div><div><strong class="tone-ok">${c.busy}</strong><span>运行任务</span></div><div><strong>${c.idle}</strong><span>空闲实例</span></div><div><strong class="${c.broken?'tone-warn':''}">${c.broken}</strong><span>需要处理</span></div></div></section>${sectionTabs([['repos','仓库与实例',bindings.length],['accounts','GitHub 账号',accounts.length],['environment','运行环境']],tab)}`;
 let content;if(tab==='repos')content=`<div class="module-layout"><section class="module-main">${c.broken?`<div class="alert-strip">${icon('info')}<span>${c.broken} 个运行器需要重新注册</span><button data-action="issues">查看 ${icon('arrow')}</button></div>`:''}<div class="module-toolbar"><label class="search">${icon('search')}<input id="repo-search" type="search" aria-label="搜索仓库" value="${esc(query)}" placeholder="搜索仓库或标签…"></label><select id="repo-filter" aria-label="仓库状态"><option value="all">全部状态</option><option value="busy">有运行任务</option><option value="attention">需要处理</option><option value="paused">已暂停</option></select><span class="toolbar-caption">每 2 秒更新</span></div><div id="repo-cards">${repoCards()}</div></section>${ciSide()}</div>`;
 else if(tab==='accounts')content=`<div class="module-section-head"><h2>已连接的 GitHub 账号</h2><button class="button small" data-action="account-add">${icon('plus')}添加账号</button></div>${accounts.length?`<section class="module-box" style="padding:0">${accounts.map(a=>`<div class="account-table-row"><div class="account-identity"><span class="account-avatar">${a.login[0].toUpperCase()}</span><span><strong>${esc(a.login)}</strong><small>${esc(a.host)}</small></span></div><div class="account-meta">${bindings.filter(b=>b.account===a.id).length} 个绑定 · ${esc(a.hint)}</div><div class="actions"><button class="button small" data-account-token="${a.id}">更换令牌</button><button class="button small danger" data-account-remove="${a.id}">删除</button></div></div>`).join('')}</section>`:empty('连接 GitHub 账号','账号用于查询可管理的仓库，并为运行器申请注册令牌。','account-add','添加账号')}<p class="module-note">${icon('lock')}令牌保存在本机；页面仅展示账号及凭据状态。</p>`;
 else content=`<div class="module-layout"><section class="module-box"><div class="box-heading"><h3>本机运行环境</h3>${state('已就绪')}</div><div class="health-list">${[['Git','运行器可以使用 git 进行检出','可用'],['官方运行器安装包','首次绑定时下载，同平台安装包复用缓存','缓存就绪'],['内核监督','进程退出后根据状态恢复运行器','已启用'],['任务期间阻止睡眠','运行任务时保持设备唤醒','已启用'],['停止等待时间','停止内核时等待当前任务完成','30 分钟']].map(([name,desc,value])=>`<div class="health-item"><span>${name}<small>${desc}</small></span>${state(value)}</div>`).join('')}</div></section><aside class="module-side"><section class="module-box"><h3>托管生命周期</h3><ol class="step-list"><li><span>启动运行器<small>由本机内核监督进程</small></span></li><li><span>等待并执行任务<small>每个实例同时处理一个任务</small></span></li><li><span>完成后继续接单<small>暂停时先等待当前任务结束</small></span></li></ol></section></aside></div>`;
 renderModule(heading+`<section id="module-panel" role="tabpanel" aria-labelledby="tab-${tab}">${content}</section><footer class="module-footer"><span>${icon('info')}本机托管 · 示例数据</span><span>GitHub Actions / xmesh</span></footer>`);if($('repo-filter'))$('repo-filter').value=statusFilter;
}
function instancePanel(b,id){const i=b.instances.find(x=>x.id===id);openPanel(i.name,`${state(stateNames[i.state],stateTone(i.state))}<div class="drawer-section">${facts([['仓库',esc(b.repo)],['当前任务',esc(i.job||'—')],['状态开始',i.since],['重启次数',i.restarts],['最近结果',esc(i.last||'—')],['实例编号',i.id]])}</div><div class="drawer-section"><h3>运行标签</h3><div class="tag-row">${['self-hosted','xmesh','xmesh-xiaosong-mac',...b.labels].map(l=>chip(l)).join('')}</div></div><div class="drawer-section"><button class="button" data-settings="${b.id}">管理仓库绑定</button></div>`,'运行器实例')}
function settingsPanel(b){openPanel(b.repo,`<p class="drawer-description">调整这个仓库在本机运行的实例数量与标签。</p>${field('并发实例','edit-concurrency',b.concurrency,{type:'number',min:1,max:16,disabled:b.source==='import',hint:b.source==='import'?'接管的运行器使用一个实例。':'每个实例同时运行一个任务，最多 16 个。'})}${field('附加标签','edit-labels',b.labels.join(', '),{hint:'用逗号或空格分隔；最多 16 个标签。'})}<p id="settings-error" class="form-error" aria-live="polite"></p>${actions('保存设置','save-settings',`data-id="${b.id}"`)}<div class="drawer-section"><h3>运行管理</h3><button class="button" data-restart="${b.id}">${icon('refresh')}重启此仓库的实例</button></div><div class="danger-zone"><h3>仓库绑定</h3><p class="small-hint">解绑前将等待正在运行的任务完成。</p><button class="button danger" style="margin-top:12px" data-unbind="${b.id}">解绑仓库</button></div>`,'仓库设置')}
function addPanel(mode='account'){bindingMode=mode;pendingBind=null;const content=mode==='account'?`${selectField('GitHub 账号','bind-account',accounts.map(a=>[a.id,a.login]),accounts[0]?.id)}${accounts.length?`<span class="small-hint">选择要在本机运行的仓库</span><div class="option-list"><label><input type="radio" name="bind-repo" value="demo-team/api" checked>demo-team/api<small>私有</small></label><label><input type="radio" name="bind-repo" value="demo-team/site">demo-team/site<small>公开</small></label></div>`:'<p class="drawer-tip">先添加 GitHub 账号，即可选择仓库。</p><button class="button" data-action="account-add">添加账号</button>'}`:mode==='token'?`${field('仓库','bind-repo','',{placeholder:'owner/repository'})}${field('一次性注册令牌','bind-token','',{type:'password',placeholder:'预览请使用示例字符',hint:'从仓库的 Actions 运行器页面获取。'})}`:`${field('已有运行器目录','bind-dir','',{placeholder:'/path/to/actions-runner'})}<p class="small-hint">接管前检查注册信息、已有服务与当前运行进程。</p>`;
 openPanel('添加仓库',`<p class="drawer-description">选择一种绑定方式，由 xmesh 托管本机运行器。</p><div class="panel-tabs" aria-label="绑定方式">${[['account','使用账号'],['token','注册令牌'],['import','接管现有']].map(([id,label])=>`<button type="button" data-bind-mode="${id}" class="${mode===id?'active':''}">${label}</button>`).join('')}</div>${content}${mode!=='import'?`<div class="form-grid">${field('并发数','bind-concurrency',1,{type:'number',min:1,max:16})}${field('附加标签','bind-labels','macOS, ARM64')}</div>`:''}<p class="form-error" id="bind-error" aria-live="polite"></p>${actions(mode==='import'?'检查目录':'预览绑定','bind-preview',!accounts.length&&mode==='account'?'disabled':'')}`,'GitHub Actions')}
function prepareBind(){let repo,source=bindingMode,account=null,concurrency=1,labels=[];if(source==='account'){repo=document.querySelector('[name="bind-repo"]:checked')?.value;account=$('bind-account').value}else if(source==='token'){repo=$('bind-repo').value.trim();if(!$('bind-token').value.trim()){return $('bind-error').textContent='请填写注册令牌。'}}else{if(!$('bind-dir').value.trim())return $('bind-error').textContent='请填写运行器目录。';repo='demo-team/imported-runner'}
 if(!repo||!/^[-\w.]+\/[-\w.]+$/.test(repo))return $('bind-error').textContent='仓库格式为 owner/repository。';if(bindings.some(b=>b.repo===repo))return $('bind-error').textContent='这个仓库已绑定。';if(source!=='import'){concurrency=Number($('bind-concurrency').value);labels=$('bind-labels').value.split(/[,\s]+/).filter(Boolean);if(!Number.isInteger(concurrency)||concurrency<1||concurrency>16)return $('bind-error').textContent='并发数需为 1–16 的整数。';if(labels.length>16||labels.some(l=>!/^[-\w.]+$/.test(l)))return $('bind-error').textContent='请检查标签格式和数量。'}
 pendingBind={id:'binding-'+Date.now(),repo,source,account,concurrency,labels,public:repo.endsWith('/site'),paused:false,instances:Array.from({length:concurrency},(_,i)=>({id:i+1,name:repo.split('/')[1]+'-mac-0'+(i+1),state:'idle',since:'19:30:00',restarts:0}))};
 openPanel('确认仓库绑定',`${facts([['仓库',esc(repo)],['方式',source==='account'?'账号授权':source==='token'?'注册令牌':'接管已有'],['并发实例',concurrency],['标签',esc(labels.join(', ')||'默认标签')]])}${source==='import'?'<div class="drawer-tip">目录检查示例：注册信息有效，当前进程已停止，可接管。</div>':''}${pendingBind.public?'<div class="detail-warning"><strong>公开仓库</strong><p>工作流代码会以本机运行用户的权限执行。来自外部的 PR 可能运行不可信代码。</p><label class="check-row"><input type="checkbox" id="confirm-public">我确认绑定这个公开仓库</label></div>':'<p class="drawer-description" style="margin-top:20px">工作流会以本机运行用户的权限执行仓库代码。</p>'}${actions('确认绑定','bind-confirm')}`,'绑定预览')}
function accountPanel(replace){openPanel(replace?'更换账号令牌':'添加 GitHub 账号',`<p class="drawer-description">用于查询可管理的仓库和申请运行器注册令牌。</p>${field('GitHub 主机','account-host',replace?.host||'github.com')}${field('个人访问令牌','account-token','',{type:'password',placeholder:'预览请使用示例字符',hint:'令牌在提交后从输入框清除。'})}<p class="form-error" id="account-error"></p>${actions('验证并保存','account-save',replace?`data-id="${replace.id}"`:'')}`,'GitHub 账号')}
document.addEventListener('input',e=>{if(e.target.id==='repo-search'){query=e.target.value;$('repo-cards').innerHTML=repoCards()}});
document.addEventListener('change',e=>{if(e.target.id==='repo-filter'){statusFilter=e.target.value;$('repo-cards').innerHTML=repoCards()}});
document.addEventListener('click',e=>{const target=e.target.closest('button,a');if(!target)return;const d=target.dataset;
 if(d.scene){scene=d.scene;bindings=scene==='empty'?[]:structuredClone(initialBindings);accounts=scene==='empty'?[]:[{id:'build-team',login:'build-team',host:'github.com',hint:'示例凭据 · 已保存'}];query='';statusFilter='all';document.querySelectorAll('[data-scene]').forEach(b=>b.setAttribute('aria-pressed',String(b===target)));render()}
 if(d.tab||d.openTab){tab=d.tab||d.openTab;render()}
 if(d.instance){const [id,n]=d.instance.split(':');instancePanel(bindings.find(b=>b.id===id),Number(n))}
 if(d.settings)settingsPanel(bindings.find(b=>b.id===d.settings));
 if(d.toggle){const b=bindings.find(b=>b.id===d.toggle);if(b.paused){b.paused=false;b.instances.forEach(i=>{if(i.state==='stopped'||i.state==='stopping')i.state=i.job?'busy':'idle'});render();notify('演示：已恢复接单')}else showConfirm('暂停 '+b.repo,'当前任务将继续完成，空闲实例停止接收新任务。','确认暂停','pause-confirm',`data-id="${b.id}"`)}
 if(d.restart)showConfirm('重启运行器','将重启此仓库的所有运行器实例。运行中的任务可能中断。','确认重启','restart-confirm',`data-id="${d.restart}"`);
 if(d.unbind)showConfirm('解绑仓库',bindings.find(b=>b.id===d.unbind).source==='import'?'解除托管并保留已有运行器目录。':'等待当前任务结束后，删除本机绑定及运行器目录。','确认解绑','unbind-confirm',`data-id="${d.unbind}"`);
 if(d.repair){const b=bindings.find(b=>b.id===d.repair);openPanel('重新注册运行器',`<p class="drawer-description">${esc(b.repo)}</p>${b.source==='account'?'<div class="drawer-tip">使用绑定账号申请新的注册令牌。</div>':field('新的注册令牌','repair-token','',{type:'password',placeholder:'预览请使用示例字符'})}<p id="repair-error" class="form-error"></p>${actions('重新注册','repair-confirm',`data-id="${b.id}"`)}`,'修复绑定')}
 if(d.bindMode)addPanel(d.bindMode);
 if(d.accountToken)accountPanel(accounts.find(a=>a.id===d.accountToken));
 if(d.accountRemove){const a=accounts.find(a=>a.id===d.accountRemove);if(bindings.some(b=>b.account===a.id))openPanel('账号正在使用',`<p class="drawer-description">${esc(a.login)} 仍有关联仓库。请先更换绑定账号或解绑这些仓库。</p><button class="button full" data-base-action="close">返回</button>`);else showConfirm('删除账号','删除本机保存的账号凭据。','确认删除','account-remove',`data-id="${a.id}"`)}
 const action=d.action;if(action==='refresh')notify('示例运行器状态已刷新');if(action==='add')addPanel();if(action==='issues'){statusFilter='attention';tab='repos';render()}if(action==='reset-search'){query='';statusFilter='all';render()}if(action==='bind-preview')prepareBind();
 if(action==='bind-confirm'&&pendingBind){if(pendingBind.public&&!$('confirm-public').checked){notify('请确认公开仓库执行风险');return}bindings.push(pendingBind);pendingBind=null;closePanel();tab='repos';query='';statusFilter='all';render();notify('演示：仓库已绑定，运行器空闲就绪')}
 if(action==='save-settings'){const b=bindings.find(b=>b.id===d.id),n=Number($('edit-concurrency').value),labels=$('edit-labels').value.split(/[,\s]+/).filter(Boolean);if(!Number.isInteger(n)||n<1||n>16||labels.length>16||labels.some(l=>!/^[-\w.]+$/.test(l))){$('settings-error').textContent='请检查并发数和标签格式。';return}b.concurrency=n;b.labels=labels;b.instances=b.instances.slice(0,n);while(b.instances.length<n){let j=b.instances.length+1;b.instances.push({id:j,name:b.id+'-mac-0'+j,state:b.paused?'stopped':'idle',since:'19:30:00',restarts:0})}closePanel();render();notify('演示：绑定设置已保存')}
 if(action==='pause-confirm'){const b=bindings.find(b=>b.id===d.id);b.paused=true;b.instances.forEach(i=>{if(i.state==='busy')i.state='stopping';else if(i.state==='idle')i.state='stopped'});closePanel();render();notify('演示：已暂停接单，当前任务继续完成')}
 if(action==='restart-confirm'){const b=bindings.find(b=>b.id===d.id);b.instances.forEach(i=>{i.state=b.paused?'stopped':'idle';delete i.job;i.restarts++});closePanel();render();notify('演示：运行器已重启')}
 if(action==='unbind-confirm'){bindings=bindings.filter(b=>b.id!==d.id);closePanel();render();notify('演示：已完成等待并解绑仓库')}
 if(action==='repair-confirm'){const b=bindings.find(b=>b.id===d.id);if(b.source!=='account'&&!$('repair-token').value.trim()){ $('repair-error').textContent='请填写新的注册令牌。';return}b.instances.forEach(i=>{if(i.state==='broken'){i.state='idle';delete i.problem}});closePanel();render();notify('演示：运行器已重新注册')}
 if(action==='account-add')accountPanel();if(action==='account-save'){if($('account-token').value.trim().length<20){$('account-error').textContent='请输入至少 20 个字符的示例令牌。';return}if(!/^[-\w.]+$/.test($('account-host').value.trim())){$('account-error').textContent='请填写主机名。';return}if(!d.id)accounts.push({id:'account-'+Date.now(),login:'demo-account',host:$('account-host').value.trim(),hint:'示例凭据 · 已保存'});closePanel();render();notify('演示：账号凭据已保存')}
 if(action==='account-remove'){accounts=accounts.filter(a=>a.id!==d.id);closePanel();render();notify('演示：账号已删除')}
});
render();
